// Tiered cascade: triggers descend, labels stay honest (plain JS)
async function cascade(tiers, input) {
  for (const tier of tiers) {
    try {
      const out = await tier.run(input);
      return { ...out, tier: tier.name, degraded: tier.name !== tiers[0].name };
    } catch (e) { /* descend: next tier tries */ }
  }
  return { tier: "human-queue", degraded: true, context: input };
}
// Tiers: [primary, secondary-model, cached-labeled, deterministic-safe-mode]
// Human queue is the terminal tier: degraded, never dead.

